examples.template:
LazyColumn(state = listState, modifier = Modifier.height(MonarchTheme.spacing.space24 * 3)) {
    item {
        MonarchText(text = {{intro}})
    }
    stickyHeader {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(MonarchTheme.colors.bgSurface)
                .padding(vertical = MonarchTheme.spacing.space2),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            MonarchText(text = {{header}}, modifier = Modifier.weight(1f), style = MonarchTextStyle.BodyStrong)
            MonarchText(text = if (pinned) {{pinnedLabel}} else {{placeLabel}}, style = MonarchTextStyle.Caption)
        }
    }
    items(items = (1..{{rows.count}}).toList(), key = { it }) { number ->
        MonarchText(text = "{{rows.prefix|raw}} $number")
    }
}

examples.code:
LazyColumn(state = listState, modifier = Modifier.height(MonarchTheme.spacing.space24 * 3)) {
    item {
        MonarchText(text = "Scroll this box.")
    }
    stickyHeader {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(MonarchTheme.colors.bgSurface)
                .padding(vertical = MonarchTheme.spacing.space2),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            MonarchText(text = "Entries", modifier = Modifier.weight(1f), style = MonarchTextStyle.BodyStrong)
            MonarchText(text = if (pinned) "Pinned" else "In place", style = MonarchTextStyle.Caption)
        }
    }
    items(items = (1..24).toList(), key = { it }) { number ->
        MonarchText(text = "Entry $number")
    }
}

Scaffold(
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 3),
    bottomBar = {
        Surface(color = MonarchTheme.colors.bgSurface) {
            MonarchButton(
                text = "Apply filters",
                onClick = {},
                modifier = Modifier.fillMaxWidth().padding(MonarchTheme.spacing.space4),
                variant = MonarchButtonVariant.Primary,
            )
        }
    },
) { padding ->
    LazyColumn(contentPadding = padding) {
        items(20) { MonarchText(text = "Filter ${it + 1}") }
    }
}

Column {
    MonarchText(text = "Activity", style = MonarchTextStyle.Heading)
    if (stuck) MonarchDivider()
    LazyColumn(state = state, modifier = Modifier.height(MonarchTheme.spacing.space24 * 2)) {
        items(30) { MonarchText(text = "Event ${it + 1}") }
    }
}
